import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, DoubleSide, Color } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Vector3 } = ctx.THREE;
  const group = new Group();

  // Create local cleanup trackers
  const timelines = [];
  const primitiveInstances = [];

  // Colors
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Build Backdrop Stage Segment (Vertical Gradient) to satisfy STAGE, never void
  const stageGeo = new PlaneGeometry(7.0, 6.0);
  const stageMat = new MeshBasicNodeMaterial({ side: DoubleSide });

  const bottomColor = vec3(
    new Color(colors.surface).r,
    new Color(colors.surface).g,
    new Color(colors.surface).b
  );
  const topColor = vec3(
    new Color(colors.ink).r * 0.7,
    new Color(colors.ink).g * 0.7,
    new Color(colors.ink).b * 0.7
  );

  stageMat.colorNode = mix(bottomColor, topColor, uv().y);
  const stageMesh = new Mesh(stageGeo, stageMat);
  stageMesh.position.set(0, 0, -2.5);
  group.add(stageMesh);

  // Core Quote Card Setup
  const cardGeo = new PlaneGeometry(4.2, 2.6);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });

  // Load Main Texture
  const defaultImageUrl = '/prism-mock/home/nodes/feature-card.png';
  const resolvedUrl = config.imageUrl ?? defaultImageUrl;
  ctx.textureLoader.loadTexture(resolvedUrl).then((tex) => {
    cardMat.colorNode = tex;
    cardMat.needsUpdate = true;
  });

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0.1);
  group.add(cardMesh);

  // Typography / Texts (Quote Content manually structured based on spec guidelines)
  const quoteText = ctx.fontAtlas.createText(
    '"PRICING REFLECTS UNCOMPROMISING HOROLOGY."',
    { fontSize: 18, color: colors.paper, align: 'center', maxWidthPx: 380 }
  );
  quoteText.position.set(0, 0.3, 0.15);
  group.add(quoteText);

  const authorText = ctx.fontAtlas.createText(
    'NOVA ATELIER CHIEF EDITOR',
    { fontSize: 10, color: colors.accent, align: 'center', letterSpacingPx: 6 }
  );
  authorText.position.set(0, -0.4, 0.15);
  group.add(authorText);

  // Local Interaction State
  let isHovered = false;

  // Interaction handlers registered in userData
  const handlers = {
    pointerover: () => {
      isHovered = true;
      gsap.killTweensOf(cardMesh.position);
      const tl = gsap.timeline();
      tl.to(cardMesh.position, {
        z: 0.25,
        y: 0.15,
        duration: 0.5,
        ease: 'power3.out'
      }).to(quoteText.position, {
        z: 0.35,
        duration: 0.5,
        ease: 'power3.out'
      }, 0);
      timelines.push(tl);
    },
    pointerout: () => {
      isHovered = false;
      gsap.killTweensOf(cardMesh.position);
      const tl = gsap.timeline();
      tl.to(cardMesh.position, {
        z: 0.1,
        y: 0,
        duration: 0.5,
        ease: 'power3.out'
      }).to(quoteText.position, {
        z: 0.15,
        duration: 0.5,
        ease: 'power3.out'
      }, 0);
      timelines.push(tl);
    },
    click: () => {
      ctx.emit('hub-pricing.select', { id: config.id });
      // Settle-down sequence
      gsap.killTweensOf(cardMesh.scale);
      const tl = gsap.timeline();
      tl.to(cardMesh.scale, {
        x: 0.96,
        y: 0.96,
        z: 0.96,
        duration: 0.12,
        ease: 'power2.out'
      })
      .to(cardMesh.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.6,
        ease: 'power4.out'
      });
      timelines.push(tl);
    }
  };

  group.userData.handlers = handlers;

  // Apply visual cinematic primitives
  const primitivesConfig = config.cinematicPrimitives ?? [
    { name: 'parallax-scroll', params: { intensity: 0.25 } }
  ];

  primitivesConfig.forEach(prim => {
    if (ctx.primitives && typeof ctx.primitives[prim.name] === 'function') {
      const inst = ctx.primitives[prim.name](group, prim.params);
      if (inst) {
        primitiveInstances.push(inst);
      }
    }
  });

  // Cleanup hook
  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill && t.kill());
    primitiveInstances.forEach(inst => {
      if (inst.cleanup) inst.cleanup();
      if (inst.timeline) inst.timeline.kill();
    });
    cardGeo.dispose();
    cardMat.dispose();
    stageGeo.dispose();
    stageMat.dispose();
  };

  return group;
}
